<?php require_once '../includes/auth.php';require_login();verify_csrf();if(is_admin())exit('Forbidden');$u=user();$date=$_POST['report_date']??today();$tot=max(0,(int)$_POST['total_students']);$pre=max(0,(int)$_POST['present']);$abs=max(0,(int)$_POST['absent']);$ws=$_POST['work_status']??'not_started';$sum=trim($_POST['work_summary']??'');if($pre+$abs>$tot)exit('Present + absent cannot exceed total students.');if(!in_array($ws,['not_started','in_progress','completed','issue'],true))exit('Invalid status.');$s=mysqli_prepare($conn,"INSERT INTO operational_reports(report_date,institution_type,institution_code,total_students,present,absent,work_status,work_summary,submitted_by) VALUES(?,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($s,'sssiiissi',$date,$u['institution_type'],$u['institution_code'],$tot,$pre,$abs,$ws,$sum,$u['id']);mysqli_stmt_execute($s);log_activity('created','reports','Submitted daily operational report',mysqli_insert_id($conn));flash('success','Daily report submitted for verification.');redirect('list.php');
